ADC_HandleTypeDef hadc1;

void MX_ADC1_Init(void) {
    ADC_ChannelConfTypeDef sConfig = {0};
    hadc1.Instance = ADC1;
    hadc1.Init.ScanConvMode = DISABLE;
    hadc1.Init.ContinuousConvMode = DISABLE;
    hadc1.Init.DiscontinuousConvMode = DISABLE;
    hadc1.Init.ExternalTrigConv = ADC_SOFTWARE_START;
    hadc1.Init.DataAlign = ADC_DATAALIGN_RIGHT;
    hadc1.Init.NbrOfConversion = 1;
    HAL_ADC_Init(&hadc1);
    sConfig.Channel = ADC_CHANNEL_0;
    sConfig.Rank = 1;
    sConfig.SamplingTime = ADC_SAMPLETIME_55CYCLES_5;
    HAL_ADC_ConfigChannel(&hadc1, &sConfig);
}

// ADC读取函数
uint16_t readADC(void) {
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, 10);  // 等待10ms
    uint16_t value = HAL_ADC_GetValue(&hadc1);
    HAL_ADC_Stop(&hadc1);
    return value;
}

// 转换为电压
float readVoltage(void) {
    uint16_t adc = readADC();
    return (float)adc / 4095.0f * 3.3f;
}

// 使用
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_ADC1_Init();
    while (1) {
        float v = readVoltage();
        printf("电压:%.2fV\r\n", v);
        HAL_Delay(500);
    }
}

// 多次采样平均
uint16_t readADCAverage(uint8_t times) {
    uint32_t sum = 0;
    for (int i = 0; i < times; i++) {
        HAL_ADC_Start(&hadc1);
        HAL_ADC_PollForConversion(&hadc1, 10);
        sum += HAL_ADC_GetValue(&hadc1);
    }
    return sum / times;
}

// 滑动平均(环形缓冲)
#define BUF_SIZE 10
uint16_t buf[BUF_SIZE];
uint8_t idx = 0;

uint16_t readADCMoving(void) {
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, 10);
    buf[idx] = HAL_ADC_GetValue(&hadc1);
    idx = (idx + 1) % BUF_SIZE;
    uint32_t sum = 0;
    for (int i = 0; i < BUF_SIZE; i++) sum += buf[i];
    return sum / BUF_SIZE;
}

/* CubeMX ADC+DMA配置
1. ADC1 → Continuous Conv: Enable
2. DMA Settings → Add → ADC1
3. DMA配置：
   - Mode: Circular(循环)
   - Data Width: Half Word(16位)
4. 生成代码
