// 用户代码
uint16_t adcBuf[8];  // DMA缓冲区

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_DMA_Init();
    MX_ADC1_Init();

    // 启动ADC+DMA
    HAL_ADC_Start_DMA(&hadc1, (uint32_t*)adcBuf, 8);

    while (1) {
        // adcBuf自动更新
        printf("ADC0=%d\r\n", adcBuf[0]);
        HAL_Delay(500);
    }
}

// 光敏电阻读取
// 接法：3.3V→光敏→ADC引脚→固定电阻→GND
// 光强：阻值小→电压高

float readLight(void) {
    uint16_t adc = readADCAverage(10);
    float voltage = adc / 4095.0f * 3.3f;
    // 映射到0-100光照等级
    int level = (int)(adc / 4095.0f * 100);
    return level;
}

// 使用
int light = readLight();
if (light < 20) {
    HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_RESET);  // 暗，开灯
} else {
    HAL_GPIO_WritePin(GPIOC, GPIO_PIN_13, GPIO_PIN_SET);    // 亮，关灯
}

// NTC温度读取(B值法)
// 接法：3.3V→固定电阻(10k)→ADC→NTC→GND

float readTemperature(void) {
    uint16_t adc = readADCAverage(10);
    float voltage = adc / 4095.0f * 3.3f;
    // 算NTC电阻
    float Rntc = 10000.0f * voltage / (3.3f - voltage);
    // B值法算温度
    float B = 3950.0f;
    float T0 = 298.15f;  // 25°C
    float R0 = 10000.0f;
    float tempK = 1.0f / (logf(Rntc / R0) / B + 1.0f / T0);
    return tempK - 273.15f;
}

// 使用
float temp = readTemperature();
printf("温度:%.1f°C\r\n", temp);

// DAC配置和使用
DAC_HandleTypeDef hdac;

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_DAC_Init();

    HAL_DAC_Start(&hdac, DAC_CHANNEL_1);

    while (1) {
        // 输出1.65V(一半)
        HAL_DAC_SetValue(&hdac, DAC_CHANNEL_1, DAC_ALIGN_12B_R, 2048);
        HAL_Delay(1000);
        // 输出0.825V(四分之一)
        HAL_DAC_SetValue(&hdac, DAC_CHANNEL_1, DAC_ALIGN_12B_R, 1024);
        HAL_Delay(1000);
    }
}

// 正弦波(查表法)
