    HAL_DAC_SetValue(&hdac, DAC_CHANNEL_1, DAC_ALIGN_12B_R, sineTable[i]);
    HAL_Delay(1);
}

// 综合示例：传感器数据采集
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_ADC1_Init();
    MX_USART1_UART_Init();
    printf("传感器数据采集\r\n");
    while (1) {
        uint16_t adc = readADCAverage(10);
        float voltage = adc / 4095.0f * 3.3f;
        int light = adc / 4095.0f * 100;
        printf("ADC=%d 电压=%.2fV 光照=%d%%\r\n", 
               adc, voltage, light);
        HAL_Delay(1000);
    }
}
